const STEP2 = `Subject: Next step for {{ collective_name }} — your application to {{ org_name }}

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}.

One step left: please fill in our application form, which asks the things we need in
order to review your project properly.

{{ form_url }}

It takes about ten minutes. If anything in it is unclear, reply to this email and a
human will get back to you.

— {{ org_name }}`;
const ADVISED_WRONG_HOST = `Subject: Your application to {{ org_name }} for {{ collective_name }} — next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}.

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. Its first impression, based only on
that:

{{ ai_applicant_message }}

That is a machine's reading of a short description — not a decision, and it may
simply be wrong. A person will review your application either way.

The next step is the same for everyone: our application form.

{{ form_url }}

If the note above missed the point of your project, the form is exactly where
to set the record straight — the more detail you give, the better the human
review. And if the other host really is the better fit, applying there instead
is completely fine.

Questions or disagreement — reply to this email and a reviewer will read it.

— {{ org_name }}`;
const ADVISED_NOT_OPEN_SOURCE = `Subject: Your application to {{ org_name }} for {{ collective_name }} — next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}.

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. Its first impression, based only on
that:

{{ ai_applicant_message }}

That is a machine's reading of what may be a very short description — not a
decision, and it may simply be wrong. A person will review your application
either way.

The next step is the same for everyone: our application form.

{{ form_url }}

If your project is open source and the note above could not tell, the form is
exactly where to show it — a repository link, the licence, how development
happens in the open. The more detail you give, the better the human review.

Questions or disagreement — reply to this email and a reviewer will read it.

— {{ org_name }}`;
const TEMPLATES = {
  fits: STEP2,
  wrong_host: ADVISED_WRONG_HOST,
  not_open_source: ADVISED_NOT_OPEN_SOURCE,
  unclear: ADVISED_NOT_OPEN_SOURCE,
};
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json;
const recipient = row.contact_email || row.applicant_email;
if (!recipient) throw new Error(`form invitation: no address for ${row.slug}`);
const raw = TEMPLATES[row.ai_verdict];
if (!raw) throw new Error(`form invitation: unknown verdict "${row.ai_verdict}" for ${row.slug}`);
const vars = {
  collective_name: row.collective_name,
  org_name: ORG_NAMES[row.org] || row.org,
  form_url: $env.FORM_URL_OSE,
  ai_applicant_message: row.ai_applicant_message,
};
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (value === undefined || value === null || value === '') {
    throw new Error(`form invitation: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const cut = raw.indexOf('\n');
let subject = render(raw.slice('Subject: '.length, cut));
const body = render(raw.slice(cut).trimStart());
const suppressed = ($env.DRY_RUN || '').toLowerCase() === 'true';
if (suppressed) subject = `[DRY_RUN → would have gone to ${recipient}] ${subject}`;
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : recipient;
if (!to) throw new Error('form invitation: DRY_RUN is true but DRY_RUN_RECIPIENT is empty');
return { json: { slug: row.slug, to, subject, body, suppressed } };

