const TEMPLATE = ':warning: *{{ collective_name }}* ({{ slug }}, applied to {{ org_name }}) needs a human decision — no activity since the last automated email. {{ collective_url }}';
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json;
const vars = {
  collective_name: row.collective_name,
  slug: row.slug,
  org_name: ORG_NAMES[row.org] || row.org,
  collective_url: row.collective_url,
};
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (value === undefined || value === null || value === '') {
    throw new Error(`escalation: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const body = render(TEMPLATE);
const channel = $env.SLACK_CHANNEL || '';
const suppressed = ($env.DRY_RUN || '').toLowerCase() === 'true';
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : channel;
if (!to) throw new Error(suppressed ? 'escalation: DRY_RUN is true but DRY_RUN_RECIPIENT is empty' : 'escalation: SLACK_CHANNEL is empty');
const subject = `[DRY_RUN → would have gone to Slack ${channel || '(no channel set)'}] Escalation for ${row.slug}`;
return { json: { slug: row.slug, to, subject, body, suppressed } };
